svg.script:
(function(){"use strict";
try{
  var bg0 = document.getElementById('bg0_280');
  var bg1 = document.getElementById('bg1_280');
  var cloth0 = document.getElementById('cloth0_280');
  var cloth1 = document.getElementById('cloth1_280');
  var watch0 = document.getElementById('watch0_280');
  var watch1 = document.getElementById('watch1_280');

  // === 1. MULTI-CLICK DYNAMIC TRAIT CUSTOMIZATION ===
  var bgState = 0;
  var clothState = 0;
  var watchState = 0;

  var clickCount = 0;
  var clickTimer = null;

  var svgEl = document.getElementById('punk-svg-280');
  if (svgEl) {
      svgEl.addEventListener('click', function(e) {
          // Ignore clicks specifically targeting the watch face color toggle
          if (e.target && e.target.getAttribute && e.target.getAttribute('class') === 'watch-face') return;

          clickCount++;
          clearTimeout(clickTimer);

          clickTimer = setTimeout(function() {
              if (clickCount === 1) {
                  bgState = 1 - bgState;
                  if (bg0) bg0.style.display = bgState ? 'none' : '';
                  if (bg1) bg1.style.display = bgState ? '' : 'none';
              } else if (clickCount === 2) {
                  clothState = 1 - clothState;
                  if (cloth0) cloth0.style.display = clothState ? 'none' : '';
                  if (cloth1) cloth1.style.display = clothState ? '' : 'none';
              } else if (clickCount >= 3) {
                  watchState = 1 - watchState;
                  if (watch0) watch0.style.display = watchState ? 'none' : '';
                  if (watch1) watch1.style.display = watchState ? '' : 'none';
                  if (watchState) tick(); // Force immediate real-time update when watch becomes visible
              }
              clickCount = 0;
          }, 400); // 400ms multi-tap window for mobile/pc
      });
  }

  // === 2. REAL-TIME WATCH CLOCK SYNC ===
  var hs = [].slice.call(document.querySelectorAll('#punk-svg-280 .hr-hand'));
  var ms = [].slice.call(document.querySelectorAll('#punk-svg-280 .mn-hand'));
  var ss = [].slice.call(document.querySelectorAll('#punk-svg-280 .sc-hand'));

  // Strip SMIL animations so JS has exclusive control
  hs.concat(ms, ss).forEach(function(el) {
    var a = el.querySelector('animateTransform');
    if (a) a.parentNode.removeChild(a);
  });

  function tick() {
    var d = new Date();
    var sec = d.getSeconds();
    var min = d.getMinutes();
    var hr = d.getHours();
    var sRot = sec * 6;
    var mRot = min * 6 + sec * 0.1;
    var hRot = (hr % 12) * 30 + min * 0.5;
    // Use SVG attribute syntax (no 'deg' unit) — reliable on hidden elements
    ss.forEach(function(e) { e.setAttribute('transform', 'rotate(' + sRot + ')'); });
    ms.forEach(function(e) { e.setAttribute('transform', 'rotate(' + mRot + ')'); });
    hs.forEach(function(e) { e.setAttribute('transform', 'rotate(' + hRot + ')'); });
  }
  tick();
  setInterval(tick, 1000);

  // Safe interactivity example: Click to toggle watch face outline color
  var faces = [].slice.call(document.querySelectorAll('#punk-svg-280 .watch-face'));
  faces.forEach(function(face) {
      face.addEventListener('click', function() {
          var colors = ['#4a4ae0', '#4ae0a0', '#e04a4a', '#e0a04a', '#ffffff'];
          var randomColor = colors[Math.floor(Math.random() * colors.length)];
          face.setAttribute('stroke', randomColor);
      });
  });
}catch(e){/* Graceful degradation — CSS animations still render if JS is blocked */}
})();
